11	declare_lint_rule! {
12	    /// Enforce that interactive ARIA roles are not assigned to non-interactive HTML elements.
13	    ///
14	    /// Non-interactive HTML elements indicate _content_ and _containers_ in the user interface.
15	    /// Non-interactive elements include `<main>`, `<h1>` (,`<h2>`, etc), `<img>`, `<li>`, `<ul>` and `<ol>`.
16	    ///
17	    /// Interactive HTML elements indicate _controls_ in the user interface.
18	    /// Interactive elements include `<a href>`, `<area>`, `<button>`, `<input>`, `<select>`, `<textarea>`.
19	    ///
20	    /// [WAI-ARIA roles](https://www.w3.org/TR/wai-aria-1.1/#usage_intro) should not be used to convert a non-interactive element to an interactive element.
21	    /// Interactive ARIA roles include `button`, `link`, `checkbox`, `menuitem`, `menuitemcheckbox`, `menuitemradio`, `option`, `radio`, `searchbox`, `switch` and `textbox`.
22	    ///
23	    /// ## Examples
24	    ///
25	    /// ### Invalid
26	    ///
27	    /// ```jsx,expect_diagnostic
28	    /// <h1 role="button">Some text</h1>
29	    /// ```
30	    ///
31	    /// ### Valid
32	    ///
33	    ///
34	    /// ```jsx
35	    /// <span role="button">Some text</span>
36	    /// ```
37	    ///
38	    /// ## Accessibility guidelines
39	    ///
40	    /// - [WCAG 4.1.2](https://www.w3.org/WAI/WCAG21/Understanding/name-role-value)
41	    ///
42	    /// ### Resources
43	    ///
44	    /// - [WAI-ARIA roles](https://www.w3.org/TR/wai-aria-1.1/#usage_intro)
45	    /// - [WAI-ARIA Authoring Practices Guide - Design Patterns and Widgets](https://www.w3.org/TR/wai-aria-practices-1.1/#aria_ex)
46	    /// - [Fundamental Keyboard Navigation Conventions](https://www.w3.org/TR/wai-aria-practices-1.1/#kbd_generalnav)
47	    /// - [Mozilla Developer Network - ARIA Techniques](https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/ARIA_Techniques/Using_the_button_role#Keyboard_and_focus)
48	    ///
49	    pub NoNoninteractiveElementToInteractiveRole {
50	        version: "next",
51	        name: "noNoninteractiveElementToInteractiveRole",
52	        language: "html",
53	        recommended: true,
54	        severity: Severity::Error,
55	        fix_kind: FixKind::Unsafe,
56	    }
57	}
