59	impl Rule for NoNoninteractiveElementToInteractiveRole {
60	    type Query = Aria<AnyHtmlTagElement>;
61	    type State = RuleState;
62	    type Signals = Option<Self::State>;
63	    type Options = NoNoninteractiveElementToInteractiveRoleOptions;
64	
65	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
66	        let node = ctx.query();
67	        let source_type = ctx.source_type::<HtmlFileSource>();
68	
69	        if node.is_custom_component() {
70	            return None;
71	        }
72	
73	        let role_attribute = node.find_attribute_by_name("role")?;
74	        let role_attribute_static_value = role_attribute
75	            .initializer()?
76	            .value()
77	            .ok()?
78	            .as_static_value()?;
79	        let role_attribute_value = role_attribute_static_value.text();
80	
81	        // Exception: role `treeitem` is allowed on `<li>`
82	        // Reason: `treeitem` has the superclass role `listitem`, which means it is made to be used on `<li>`
83	        // Ref: https://w3c.github.io/aria/#treeitem
84	        // Ref: https://www.w3.org/WAI/ARIA/apg/patterns/treeview/examples/treeview-1a/
85	        if is_html_tag(node, source_type, "li") && role_attribute_value == "treeitem" {
86	            return None;
87	        }
88	
89	        if ctx.aria_roles().is_not_interactive_element(node)
90	            && AriaRole::from_roles(role_attribute_value).is_some_and(|role| role.is_interactive())
91	        {
92	            // <div> and <span> are considered neither interactive nor non-interactive, depending on the presence or absence of the role attribute.
93	            // We don't report <div> and <span> here, because we cannot determine whether they are interactive or non-interactive.
94	            if ROLE_SENSITIVE_ELEMENTS
95	                .iter()
96	                .any(|el| is_html_tag(node, source_type, el))
97	            {
98	                return None;
99	            }
100	
101	            return Some(RuleState {
102	                attribute_range: role_attribute.range(),
103	                element_name: node.tag_name()?,
104	            });
105	        }
106	
107	        None
108	    }
109	
110	    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
111	        let element_name = state.element_name.text();
112	        Some(RuleDiagnostic::new(
113	            rule_category!(),
114	            state.attribute_range,
115	            markup! {
116	                "The HTML element "<Emphasis>{{element_name}}</Emphasis>" is non-interactive and should not have an interactive role."
117	            },
118	        ).note(
119	            markup!{
120	                "Replace "<Emphasis>{{element_name}}</Emphasis>" with a div or a span."
121	            }
122	        ))
123	    }
124	
125	    fn action(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<HtmlRuleAction> {
126	        let node = ctx.query();
127	        let role_attribute = node.find_attribute_by_name("role")?;
128	
129	        let mut mutation = ctx.root().begin();
130	        mutation.remove_node(role_attribute);
131	        Some(HtmlRuleAction::new(
132	            ctx.metadata().action_category(ctx.category(), ctx.group()),
133	            ctx.metadata().applicability(),
134	            markup! { "Remove the "<Emphasis>"role"</Emphasis>" attribute." }.to_owned(),
135	            mutation,
136	        ))
137	    }
138	}
