    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();

        if node.is_custom_component() {
            return None;
        }

        if ctx.aria_roles().is_not_interactive_element(node) {
            let role_attribute = node.find_attribute_by_name("role")?;
