71	/// Run the analyzer on the provided `root`: this process will use the given `filter`
72	/// to selectively restrict analysis to specific rules / a specific source range,
73	/// then call `emit_signal` when an analysis rule emits a diagnostic or action.
74	/// Additionally, this function takes a `inspect_matcher` function that can be
75	/// used to inspect the "query matches" emitted by the analyzer before they are
76	/// processed by the lint rules registry
77	pub fn analyze_with_inspect_matcher<'a, V, F, B>(
78	    root: &LanguageRoot<HtmlLanguage>,
79	    filter: AnalysisFilter,
80	    inspect_matcher: V,
81	    options: &'a AnalyzerOptions,
82	    source_type: HtmlFileSource,
83	    html_services: HtmlAnalyzerServices,
84	    mut emit_signal: F,
85	) -> (Option<B>, Vec<Error>)
86	where
87	    V: FnMut(&MatchQueryParams<HtmlLanguage>) + 'a,
88	    F: FnMut(&dyn AnalyzerSignal<HtmlLanguage>) -> ControlFlow<B> + 'a,
89	    B: 'a,
