91	    fn parse_linter_suppression_comment(
92	        text: &str,
93	        piece_range: TextRange,
94	    ) -> Vec<Result<AnalyzerSuppression<'_>, SuppressionDiagnostic>> {
95	        let mut result = Vec::new();
96	
97	        for suppression in parse_suppression_comment(text) {
98	            let suppression = match suppression {
99	                Ok(suppression) => suppression,
100	                Err(err) => {
101	                    result.push(Err(err));
102	                    continue;
103	                }
104	            };
105	
106	            let analyzer_suppressions: Vec<_> = to_analyzer_suppressions(suppression, piece_range)
107	                .into_iter()
108	                .map(Ok)
109	                .collect();
110	
111	            result.extend(analyzer_suppressions)
112	        }
113	
114	        result
115	    }
116	
117	    let mut registry = RuleRegistry::builder(&filter, root);
118	    visit_registry(&mut registry);
119	
120	    let (registry, mut services, diagnostics, visitors) = registry.build();
121	
122	    // Bail if we can't parse a rule option
123	    if !diagnostics.is_empty() {
124	        return (None, diagnostics);
125	    }
126	
127	    services.insert_service(source_type);
128	    services.insert_service(Arc::new(AriaRoles));
129	    if let Some(module_graph) = html_services.module_graph {
130	        services.insert_service(module_graph);
131	    }
132	    if let Some(project_layout) = html_services.project_layout {
133	        services.insert_service(project_layout);
134	    }
135	
136	    let mut analyzer = biome_analyze::Analyzer::new(
137	        METADATA.deref(),
138	        biome_analyze::InspectMatcher::new(registry, inspect_matcher),
139	        parse_linter_suppression_comment,
140	        Box::new(HtmlSuppressionAction),
141	        &mut emit_signal,
142	    );
143	
144	    for ((phase, _), visitor) in visitors {
145	        analyzer.add_visitor(phase, visitor);
146	    }
147	
148	    (
149	        analyzer.run(biome_analyze::AnalyzerContext {
150	            root: root.clone(),
151	            range: filter.range,
152	            services,
153	            options,
154	        }),
155	        diagnostics,
156	    )
157	}
